from math import floor

def drand48(seed):
    x=(seed<<16)+0x330e
    while True:
        x=(0x5DEECE66D*x + 0xB) & ((1<<48)-1)
        yield x/(1<<48)

def sample_onepass(nrec, nout, seed):
    res=list(range(1, nout+1))
    g=drand48(seed)
    for i in range(nout+1, nrec+1):
        j=int(next(g)*i)
        if j < nout:
            res[j]=i
    return res

def sample_frac(nrec, frac, seed):
    g=drand48(seed)
    out=[]
    for i in range(1,nrec+1):
        if next(g) < frac:
            out.append(i)
    return out
for seed in [11,1,100]:
    print('seed',seed,'count3',sample_onepass(10,3,seed),'frac0.3',sample_frac(10,0.3,seed),'frac0.5(3rec)',sample_frac(3,0.5,seed),'count2(3rec)',sample_onepass(3,2,seed))
PY"

