#include <bits/stdc++.h>
using namespace std;
vector<int> cnt(int n, int k, uint64_t seed){
    mt19937_64 rng(seed);
    vector<int> res;
    for(int i=1;i<=n && i<=k;i++) res.push_back(i);
    for(int i=k+1;i<=n;i++){
        uniform_int_distribution<int> dist(0, i-1);
        int j = dist(rng);
        if(j < k) res[j] = i;
    }
    return res;
}
vector<int> cntmod(int n,int k,uint64_t seed){
    mt19937_64 rng(seed);
    vector<int> res;
    for(int i=1;i<=n && i<=k;i++) res.push_back(i);
    for(int i=k+1;i<=n;i++){
        int j = (int)(rng() % i);
        if(j < k) res[j] = i;
    }
    return res;
}
