    mt19937_64 rng(seed);
    uniform_real_distribution<double> dist(0.0,1.0);
    vector<int> res;
    for(int i=1;i<=n && i<=k;i++) res.push_back(i);
    for(int i=k+1;i<=n;i++){
        int j = (int)(dist(rng) * (i+1));
        if(j < k) res[j] = i;
    }
    return res;
}
