#include <bits/stdc++.h>
using namespace std;
vector<int> floyd(int n,int k,uint64_t seed){
    mt19937_64 rng(seed);
    unordered_set<int> s;
    vector<int> order;
    for(int j=n-k+1;j<=n;j++){
        uniform_int_distribution<int> dist(1,j);
        int t=dist(rng);
        int x = s.count(t)? j : t;
        s.insert(x);
        order.push_back(x);
    }
    return order;
}
