#include <bits/stdc++.h>
using namespace std;
vector<int> partial(int n,int k,uint64_t seed){
    mt19937_64 rng(seed);
    vector<int> v(n); iota(v.begin(), v.end(), 1);
    for(int i=0;i<k;i++){
        uniform_int_distribution<int> dist(i,n-1);
        int j=dist(rng);
        swap(v[i],v[j]);
    }
    v.resize(k);
    return v;
}
