vector<int> reservoir_int(mt19937_64 rng,int n,int k){vector<int> r; for(int i=1;i<=min(n,k);++i) r.push_back(i); for(int i=k+1;i<=n;++i){uniform_int_distribution<int>d(0,i-1); int j=d(rng); if(j<k) r[j]=i;} return r;}
