vector<int> seqf(mt19937_64 rng,int n,int k){vector<int> out; uniform_real_distribution<double>d(0,1); int rem=k; for(int i=1;i<=n&&rem;i++){ if(d(rng) < (double)rem/(n-i+1)){ out.push_back(i); rem--; } } return out; }
