fn cmd_sample(args: &[String]) -> i32 {
    let mut two_pass = false;
    let mut seed: u64 = 11;
    let mut positional = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if arg.starts_with('-') && arg != "-" {
            if arg == "-2" {
                two_pass = true;
            } else if let Some(rest) = arg.strip_prefix("-s") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{SAMPLE_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                seed = value.parse::<u64>().unwrap_or(11);
            } else {
                print!("{SAMPLE_USAGE}");
                return 1;
            }
        } else {
            positional.push(arg.clone());
        }
        i += 1;
    }
    if positional.len() < 2 {
        print!("{SAMPLE_USAGE}");
        return 1;
    }
    let input = &positional[0];
    let sample_arg = &positional[1];
    let (records, format) = match read_fastx(Some(input)) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_sample] failed to open the input file/stream.");
            return 1;
        }
    };
    let out_format = format.unwrap_or(Format::Fasta);
    let mut out = BufWriter::new(io::stdout().lock());
    let parsed = sample_arg.parse::<f64>().unwrap_or(0.0);
    if parsed >= 1.0 {
        let n = (parsed + 0.499).floor() as usize;
        let mut rng = Mt19937_64::new(seed);
        let mut reservoir: Vec<(usize, Record)> = Vec::new();
        for (idx, record) in records.into_iter().enumerate() {
            if idx < n {
                reservoir.push((idx, record));
            } else if n > 0 {
                let j = (rng.next_f64() * (idx as f64 + 1.0)).floor() as usize;
                if j < n {
                    reservoir[j] = (idx, record);
                }
            }
        }
        if two_pass {
            reservoir.sort_by_key(|(idx, _)| *idx);
        }
        for (_, record) in reservoir {
            let _ = write_record(&mut out, &record, out_format, 0, None);
        }
    } else {
        let frac = parsed;
        if two_pass {
            eprint!("[W::stk_sample] when sampling a fraction, option -2 is ignored.");
        }
        let mut rng = Mt19937_64::new(seed);
        for record in records {
            if rng.next_f64() < frac {
                let _ = write_record(&mut out, &record, out_format, 0, None);
            }
        }
    }
    0
}

