fn cmd_mergefa(args: &[String]) -> i32 {
    let mut qcut = 0i32;
    let mut intersect = false;
    let mut lower_n = false;
    let mut random_het = false;
    let mut suppress_het = false;
    let mut positional = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if arg.starts_with('-') && arg != "-" {
            if let Some(rest) = arg.strip_prefix("-q") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        print!("{MERGEFA_USAGE}");
                        return 1;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                qcut = parse_i32(&value, 0);
            } else if arg == "-i" {
                intersect = true;
            } else if arg == "-m" {
                lower_n = true;
            } else if arg == "-r" {
                random_het = true;
            } else if arg == "-h" {
                suppress_het = true;
            } else {
                print!("{MERGEFA_USAGE}");
                return 1;
            }
        } else {
            positional.push(arg.clone());
        }
        i += 1;
    }
    if positional.len() < 2 {
        print!("{MERGEFA_USAGE}");
        return 1;
    }
    let (left, _) = match read_fastx(Some(&positional[0])) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_mergefa] failed to open the input file/stream.");
            return 1;
        }
    };
    let (right, _) = match read_fastx(Some(&positional[1])) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_mergefa] failed to open the input file/stream.");
            return 1;
        }
    };
    let mut stats = [0usize; 5];
    let mut bit_rng = PatternRng::new();
    let mut out_records = Vec::new();
    let count = max(left.len(), right.len());
    for idx in 0..count {
        let a = left.get(idx);
        let b = right.get(idx);
        let Some(name) = a.map(|r| r.name.clone()).or_else(|| b.map(|r| r.name.clone())) else {
            continue;
        };
        if let (Some(ar), Some(br)) = (a, b) {
            if ar.name != br.name {
                eprintln!("[stk_mergefa] Different sequence names: {} != {}", ar.name, br.name);
            }
            if ar.seq.len() != br.seq.len() {
                eprintln!(
                    "[stk_mergefa] Unequal sequence length: {} != {}",
                    ar.seq.len(),
                    br.seq.len()
                );
            }
        }
        let len = max(a.map_or(0, Record::len), b.map_or(0, Record::len));
        let mut merged = Vec::with_capacity(len);
        for pos in 0..len {
            let ba = a.and_then(|r| r.seq.get(pos).copied()).unwrap_or(b'N');
            let bb = b.and_then(|r| r.seq.get(pos).copied()).unwrap_or(b'N');
            let qa = a.and_then(|r| r.qual.as_ref()).and_then(|q| q.get(pos).copied());
            let qb = b.and_then(|r| r.qual.as_ref()).and_then(|q| q.get(pos).copied());
            let left_bits = allele_bits(ba);
            let right_bits = allele_bits(bb);
            let stats_allowed = if qcut > 0 {
                let qa_ok = qa.map(|q| (q as i32 - 33) >= qcut).unwrap_or(true);
                let qb_ok = qb.map(|q| (q as i32 - 33) >= qcut).unwrap_or(true);
                qa_ok && qb_ok
            } else {
                true
            };
            if stats_allowed {
                let la = classify_mergefa_stat(ba);
                let lb = classify_mergefa_stat(bb);
                match (la, lb) {
                    (Some(0), Some(0)) => {
                        if ba.eq_ignore_ascii_case(&bb) {
                            stats[0] += 1;
                        } else {
                            stats[1] += 1;
                        }
                    }
                    (Some(0), Some(1)) => stats[2] += 1,
                    (Some(1), Some(0)) => stats[3] += 1,
                    (Some(1), Some(1)) => stats[4] += 1,
                    _ => {}
                }
            }

            let lower_in = ba.is_ascii_lowercase() || bb.is_ascii_lowercase();
            let mut out_base = if lower_n {
                if is_n(ba) || is_n(bb) {
                    let other = if is_n(ba) { bb } else { ba };
                    if is_n(other) {
                        b'n'
                    } else {
                        other.to_ascii_lowercase()
                    }
                } else {
                    encode_alleles(left_bits & right_bits, lower_in, b'x')
                }
            } else if intersect {
                encode_alleles(left_bits & right_bits, lower_in, b'x')
            } else {
                encode_alleles(left_bits | right_bits, lower_in, b'x')
            };

            if suppress_het && (is_ambiguous_input(ba) || is_ambiguous_input(bb)) {
                out_base = out_base.to_ascii_lowercase();
            }
            if qcut > 0 {
                let low = qa.map(|q| (q as i32 - 33) < qcut).unwrap_or(false)
                    || qb.map(|q| (q as i32 - 33) < qcut).unwrap_or(false);
                if low {
                    out_base = out_base.to_ascii_lowercase();
                }
            }
            if random_het && is_het2(out_base) {
                let alleles = decode_het2(out_base);
                out_base = alleles[bit_rng.next_bit()];
                if lower_in || suppress_het {
                    out_base = out_base.to_ascii_lowercase();
                }
            }
            merged.push(out_base);
        }
        out_records.push(Record {
            name,
            comment: None,
            seq: merged,
            qual: None,
        });
    }
    eprintln!(
        "[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=({},{},{},{},{})",
        stats[0], stats[1], stats[2], stats[3], stats[4]
    );
    let mut out = BufWriter::new(io::stdout().lock());
