fn cmd_telo(args: &[String]) -> i32 {
    let mut min_score: Option<usize> = None;
    let mut _drop = 5usize;
    let mut motif = b"TTAGGG".to_vec();
    let mut mono: Option<u8> = None;
    let mut positional = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if arg.starts_with('-') && arg != "-" {
            if let Some(rest) = arg.strip_prefix("-s") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        eprintln!("telo: invalid option -- 's'");
                        return 0;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                min_score = Some(parse_usize(&value, 1));
            } else if let Some(rest) = arg.strip_prefix("-d") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        eprintln!("telo: invalid option -- 'd'");
                        return 0;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                _drop = parse_usize(&value, 5);
            } else if let Some(rest) = arg.strip_prefix("-p") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        eprintln!("telo: invalid option -- 'p'");
                        return 0;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                motif = value.into_bytes();
            } else if let Some(rest) = arg.strip_prefix("-m") {
                let value = if rest.is_empty() {
                    i += 1;
                    if i >= args.len() {
                        eprintln!("telo: invalid option -- 'm'");
                        return 0;
                    }
                    args[i].clone()
                } else {
                    rest.to_string()
                };
                mono = value.as_bytes().first().copied();
            } else {
                eprintln!("telo: invalid option -- '{}'", arg.trim_start_matches('-'));
                return 0;
            }
        } else {
            positional.push(arg.clone());
        }
        i += 1;
    }
    let input = positional.first().map(String::as_str);
    let (records, format) = match read_fastx(input) {
        Ok(v) => v,
        Err(_) => {
            eprintln!("[E::stk_telo] failed to open the input file/stream.");
            return 1;
        }
    };
    if format == Some(Format::Fastq) {
        eprintln!("0\t0");
        return 0;
    }
    let mut total_bases = 0usize;
    let mut hit_bases = 0usize;
    let mut out = BufWriter::new(io::stdout().lock());
    for record in records {
        total_bases += record.seq.len();
        for (start, end) in telo_hits(&record.seq, min_score, &motif, mono) {
            hit_bases += end - start;
            if min_score.is_some() {
                let _ = writeln!(out, "{}\t{}\t{}\t{}", record.name, start, end, record.seq.len());
            } else {
                let _ = writeln!(out, "{}\t{}\t{}", record.name, start, end);
            }
        }
    }
    eprintln!("{}\t{}", hit_bases, total_bases);
    0
}

#[derive(Default, Clone)]
struct PosStats {
    bases: usize,
    a: usize,
    c: usize,
    g: usize,
    t: usize,
    n: usize,
    q_sum: i64,
    err_sum: f64,
    low: usize,
    high: usize,
}

impl PosStats {
    fn add(&mut self, base: u8, q: i32, qcut: i32) {
        self.bases += 1;
        match base.to_ascii_lowercase() {
            b'a' => self.a += 1,
            b'c' => self.c += 1,
            b'g' => self.g += 1,
            b't' | b'u' => self.t += 1,
            _ => self.n += 1,
        }
        self.q_sum += q as i64;
        self.err_sum += (10f64.powf(-(q as f64) / 10.0)).min(0.5);
        if q < qcut {
            self.low += 1;
        } else {
            self.high += 1;
        }
    }
}

fn print_pos_stats(label: &str, stats: &PosStats) {
    if stats.bases == 0 {
        println!("{label}\t0\t0.0\t0.0\t0.0\t0.0\t0.0\t0.0\t0.0\t0.0\t0.0");
        return;
    }
    let denom = stats.bases as f64;
    let avg_q = stats.q_sum as f64 / denom;
    let err_q = -10.0 * (stats.err_sum / denom).log10();
    println!(
        "{label}\t{}\t{:.1}\t{:.1}\t{:.1}\t{:.1}\t{:.1}\t{:.1}\t{:.1}\t{:.1}\t{:.1}",
        stats.bases,
        100.0 * stats.a as f64 / denom,
        100.0 * stats.c as f64 / denom,
        100.0 * stats.g as f64 / denom,
        100.0 * stats.t as f64 / denom,
        100.0 * stats.n as f64 / denom,
        avg_q,
        err_q,
        100.0 * stats.low as f64 / denom,
        100.0 * stats.high as f64 / denom
    );
}

