vector<int> reservoir_real(mt19937_64 rng,int n,int k){vector<int> r; for(int i=1;i<=min(n,k);++i) r.push_back(i); uniform_real_distribution<double>d(0,1); for(int i=k+1;i<=n;++i){int j=(int)(d(rng)*i); if(j<k) r[j]=i;} return r;}
vector<int> reservoir_int(mt19937_64 rng,int n,int k){vector<int> r; for(int i=1;i<=min(n,k);++i) r.push_back(i); for(int i=k+1;i<=n;++i){uniform_int_distribution<int>d(0,i-1); int j=d(rng); if(j<k) r[j]=i;} return r;}
vector<int> reservoir_mod(mt19937_64 rng,int n,int k){vector<int> r; for(int i=1;i<=min(n,k);++i) r.push_back(i); for(int i=k+1;i<=n;++i){int j=rng()%i; if(j<k) r[j]=i;} return r;}
vector<int> seqf(mt19937_64 rng,int n,int k){vector<int> out; uniform_real_distribution<double>d(0,1); int rem=k; for(int i=1;i<=n&&rem;i++){ if(d(rng) < (double)rem/(n-i+1)){ out.push_back(i); rem--; } } return out; }
