vector<int> floyd(mt19937_64 rng,int n,int k){ unordered_set<int>s; vector<int>o; for(int j=n-k+1;j<=n;j++){ uniform_int_distribution<int>d(1,j); int t=d(rng); int x=s.count(t)?j:t; s.insert(x); o.push_back(x);} return o; }
vector<int> partial(mt19937_64 rng,int n,int k){ vector<int>v(n); iota(v.begin(),v.end(),1); for(int i=0;i<k;i++){ uniform_int_distribution<int>d(i,n-1); int j=d(rng); swap(v[i],v[j]); } v.resize(k); return v; }
vector<int> sample_std(mt19937_64 rng,int n,int k){ vector<int>v(n); iota(v.begin(),v.end(),1); vector<int>o; sample(v.begin(),v.end(),back_inserter(o),k,rng); return o; }
