template<class R> V reservoir_mod(unsigned seed,int n,int k){ R r(seed); V v; for(int i=1;i<=k;i++) v.push_back(i); for(int i=k+1;i<=n;i++){ int j=(unsigned long long)r.next()%i; if(j<k) v[j]=i; } return v; }
template<class R> V partial_mod(unsigned seed,int n,int k){ R r(seed); V v(n); iota(v.begin(),v.end(),1); for(int i=0;i<k;i++){ int j=i + ((unsigned long long)r.next() % (n-i)); swap(v[i],v[j]); } v.resize(k); return v; }
template<class R> V shuffle_mod(unsigned seed,int n,int k){ R r(seed); V v(n); iota(v.begin(),v.end(),1); for(int i=n-1;i>0;i--){ int j=(unsigned long long)r.next() % (i+1); swap(v[i],v[j]); } v.resize(k); return v; }
